import outbreak_detection;

class LocationStats {
    location_name: string;
    case_count: int;
}

class OutbreakStatus {
    status: string;
    threshold: int;
}

func compute_location_stats(locations) {
    let total_cases := 0;
    let max_cases := 0;
    let count := 0;

    for (let i := 0; i < locations.length; i := i + 1) {
        let loc := locations[i];
        total_cases := total_cases + loc.case_count;
        if (loc.case_count > max_cases) {
            max_cases := loc.case_count;
        }
        count := count + 1;
    }

    if (count == 0) {
        return null;
    }

    let avg := total_cases / count;
    let threshold := avg * 2;

    let status := new OutbreakStatus {
        status := "No Outbreak",
        threshold := threshold,
    };

    if (max_cases > threshold) {
        status.status := "Outbreak Detected";
    }

    return status;
}

