class CVDAnalysisResult {
    patient_id: string;
    age: int;
    risk_score: real;
    risk_level: string;
}

func sort_patients_by_age_desc(patients) {
    let n := length(patients);
    let sorted := new Array { };
    for (let i := 0; i < n; i := i + 1) {
        sorted.append(patients[i]);
    }
    for (let i := 0; i < n - 1; i := i + 1) {
        for (let j := i + 1; j < n; j := j + 1) {
            if (sorted[i].age < sorted[j].age) {
                let temp := sorted[i];
                sorted[i] := sorted[j];
                sorted[j] := temp;
            }
        }
    }
    return sorted;
}

func run_cvd_batch_analysis(patients) {
    let sorted_patients := sort_patients_by_age_desc(patients);
    let results := new Array { };
    for (let i := 0; i < length(sorted_patients); i := i + 1) {
        let p := sorted_patients[i];
        let risk := healthcare.analyze_heart_disease(p);
        let risk_level := "low";
        if (risk.risk_score >= 50) {
            risk_level := "medium";
        } else if (risk.risk_score >= 75) {
            risk_level := "high";
        }
        let result := new CVDAnalysisResult {
            patient_id := p.patient_id,
            age := p.age,
            risk_score := risk.risk_score,
            risk_level := risk_level,
        };
        results.append(result);
    }
    return results;
}

