    let is_declining := rt_estimate < 1.0;
    if (is_declining) {
        println(location + ": Epidemic is declining (Rt = " + rt_estimate + ")");
    } else {
        println(location + ": Epidemic is NOT declining (Rt = " + rt_estimate + ")");
    }
}

