func compute_mean_bp_by_gender(bp_values, genders) {
    let total_bp := 0;
    let count := 0;
    let males := 0;
    let females := 0;
    let male_sum := 0;
    let female_sum := 0;

    for (let i := 0; i < bp_values.length; i := i + 1) {
        let bp := bp_values[i];
        let gender := genders[i];
        total_bp := total_bp + bp;
        count := count + 1;

        if (gender == "Male") {
            males := males + 1;
            male_sum := male_sum + bp;
        } else if (gender == "Female") {
            females := females + 1;
            female_sum := female_sum + bp;
        }
    }

    let mean_male := 0;
    let mean_female := 0;

    if (males > 0) {
        mean_male := male_sum / males;
    }

    if (females > 0) {
        mean_female := female_sum / females;
    }

    return {
        male_mean := mean_male,
        female_mean := mean_female,
        male_count := males,
        female_count := females,
    };
}

