func detect_new_cases_outliers(stats_array) {
    let new_cases_values := [];
    for (let i := 0; i < stats_array.length; i := i + 1) {
        let loc := stats_array[i];
        new_cases_values := new_cases_values + [loc.new_cases];
    }
    let mean := statistics.mean(new_cases_values);
    let std_dev := statistics.std_dev(new_cases_values);
    let outliers := [];
    for (let i := 0; i < stats_array.length; i := i + 1) {
        let loc := stats_array[i];
        let deviation := (loc.new_cases - mean) / std_dev;
        if (deviation > 2.0 || deviation < -2.0) {
            let outlier := new Outlier {
                location := loc.location,
                value := loc.new_cases,
                deviation := deviation,
            };
            outliers := outliers + [outlier];
        }
    }
    return outliers;
}

