func compute_group_stats(group) {
    let count := 0;
    let sum := 0;
    for (let i := 0; i < group.heart_rates.length; i := i + 1) {
        let hr := group.heart_rates[i];
        sum := sum + hr;
        count := count + 1;
    }
    let mean := sum / count;
    let max := 0;
    for (let i := 0; i < group.heart_rates.length; i := i + 1) {
        let hr := group.heart_rates[i];
        if (hr > max) {
            max := hr;
        }
    }
    return new HeartRateGroup {
        gender := group.gender,
        count := count,
        sum := sum,
        mean := mean,
        max := max,
    };
}

