class GenderGroup {
    gender: string;
    count: int;
    sum_bp: int;
}

func compute_mean_bp_by_gender(ds) {
    let groups := [];
    let temp_map := {};

    let patients := healthcare.read_patients(ds);
    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        let g := p.gender;
        if (temp_map[g] == null) {
            temp_map[g] := new GenderGroup {
                gender := g,
                count := 0,
                sum_bp := 0,
            };
        }
        let group := temp_map[g];
        group.count := group.count + 1;
        group.sum_bp := group.sum_bp + p.vital_signs.blood_pressure;
    }

    let final_groups := [];
    for (let key in temp_map.keys()) {
        let group := temp_map[key];
        final_groups := final_groups + [group];
    }

    let results := [];
    for (let i := 0; i < final_groups.length; i := i + 1) {
        let g := final_groups[i];
        let mean := g.sum_bp / g.count;
        results := results + [new healthcare.GroupedResult {
            group_name := g.gender,
            mean_blood_pressure := mean,
            count := g.count,
        }];
    }

    return results;
}

