class VitalSigns {
    blood_pressure: int;
    heart_rate: int;
}

class OutlierResult {
    patient_id: string;
    blood_pressure: int;
    is_high: bool;
    is_low: bool;
}

func detect_outliers(ds) {
    let patients := healthcare.load_patients(ds);
    let bp_values := [];
    let outliers := [];

    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        bp_values := bp_values + [p.vital_signs.blood_pressure];
    }

    let q1 := healthcare.calculate_q1(bp_values);
    let q3 := healthcare.calculate_q3(bp_values);
    let iqr := q3 - q1;
    let lower_bound := q1 - 1.5 * iqr;
    let upper_bound := q3 + 1.5 * iqr;

    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        let bp := p.vital_signs.blood_pressure;
        let is_low := bp < lower_bound;
        let is_high := bp > upper_bound;
        let outlier := new OutlierResult {
            patient_id := p.patient_id,
            blood_pressure := bp,
            is_high := is_high,
            is_low := is_low,
        };
        outliers := outliers + [outlier];
    }

    return outliers;
}

