import epidemiology;

class LocationStats {
    location: string;
    mean_new_cases: real;
    estimated_reproduction_number: real;
}

func compute_location_stats(location_data) {
    let grouped := group_by(location_data, "location");
    let stats := [];
    for (let loc := 0; loc < length(grouped); loc := loc + 1) {
        let loc_name := grouped[loc].location;
        let cases := grouped[loc].new_cases;
        let mean_cases := mean(cases);
        let r_est := estimate_reproduction_number(cases);
        let stat := new LocationStats {
            location := loc_name,
            mean_new_cases := mean_cases,
            estimated_reproduction_number := r_est,
        };
        stats.append(stat);
    }
    return stats;
}

