class LocationStats {
    location_name: string;
    case_count: int;
    baseline_average: real;
}

func calculate_outbreak_thresholds(locations) {
    let total_cases := 0;
    let total_locations := 0;

    for (let i := 0; i < locations.length; i := i + 1) {
        let loc := locations[i];
        total_cases := total_cases + loc.case_count;
        total_locations := total_locations + 1;
    }

    let avg_cases := total_cases / total_locations;
    let threshold := avg_cases * 1.5;

    return threshold;
}

let input_ds := new Data { name := "outbreak_cases" };

