let threshold := calculate_outbreak_thresholds(stats_list);

let outbreak_locations := [];

for (let i := 0; i < stats_list.length; i := i + 1) {
    let loc := stats_list[i];
    if (loc.case_count > threshold) {
        let entry := new LocationStats {
            location_name := loc.location_name,
            case_count := loc.case_count,
            baseline_average := loc.baseline_average,
        };
        outbreak_locations := outbreak_locations + [entry];
    }
}

