func count_by_gender(patients) {
    let counts := new GenderCounts {
        male := 0,
        female := 0,
    };
    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        if (p.gender == "M") {
            counts.male := counts.male + 1;
        } else if (p.gender == "F") {
            counts.female := counts.female + 1;
        }
    };
    return counts;
}

func compute_spo2_stats(patients) {
    let min := 100;
    let max := 0;
    let sum := 0.0;
    let count := 0;
    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        let spo2 := p.spo2;
        if (spo2 < min) {
            min := spo2;
        };
        if (spo2 > max) {
            max := spo2;
        };
        sum := sum + spo2;
        count := count + 1;
    };
    let mean := 0.0;
    if (count > 0) {
        mean := sum / real(count);
    };
    return new Spo2Stats {
        min := min,
        max := max,
        mean := mean,
        count := count,
    };
}

