func count_by_location(epidemics) {
    let counts := [];
    let seen := [];

    for (let i := 0; i < epidemics.length; i := i + 1) {
        let e := epidemics[i];
        let loc := e.location;

        let found := false;
        for (let j := 0; j < seen.length; j := j + 1) {
            if (seen[j].name == loc.name) {
                found := true;
                seen[j].count := seen[j].count + 1;
                break;
            }
        }

        if (!found) {
            seen.push(new EpidemicStats {
                name := loc.name,
                count := 1,
            });
        }
    }

    return seen;
}

