func count_conditions_by_type(all_patients) {
    let counts := [0, 0, 0, 0, 0]; // Placeholder for 5 common conditions
    let condition_names := ["Hypertension", "Diabetes", "COPD", "Heart Disease", "Kidney Disease"];

    for (let i := 0; i < 5; i := i + 1) {
        counts[i] := 0;
    }

    for (let p := 0; p < all_patients.length; p := p + 1) {
        let patient := all_patients[p];
        for (let c := 0; c < patient.chronic_conditions.length; c := c + 1) {
            let cond := patient.chronic_conditions[c];
            for (let i := 0; i < 5; i := i + 1) {
                if (cond.name == condition_names[i]) {
                    counts[i] := counts[i] + 1;
