func normalize_hba1c_zscore(data) {
    let hba1c_values := healthcare.read_column(data, "hba1c");
    let mean := healthcare.mean(hba1c_values);
    let std := healthcare.std(hba1c_values);
    let normalized := healthcare.map(hba1c_values, func(x) {
        return (x - mean) / std;
    });
    return healthcare.update_column(data, "hba1c", normalized);
}

