import epidemiology;

class LocationStats {
    location_name: string;
    cases: int;
    population: int;
    rate_per_100k: real;
}

func compute_location_stats(loc) {
    let result := epidemiology.compute_cumulative_incidence(loc);
    let cases := result.cases;
    let pop := result.population;
    let rate := (cases / pop) * 100000.0;
    return new LocationStats {
        location_name := loc.name,
        cases := cases,
        population := pop,
        rate_per_100k := rate,
    };
}

