func detect_outliers(patients) {
    let high_outliers := [];
    let low_outliers := [];

    for (let i := 0; i < patients.length; i := i + 1) {
        let p := patients[i];
        let hr := p.vital_signs.heart_rate;

        if (hr > 100) {
            high_outliers := high_outliers + [p];
        } else if (hr < 40) {
            low_outliers := low_outliers + [p];
        }
    }

    return [high_outliers, low_outliers];
}

