class LocationStats {
    location_name: string;
    case_count: int;
    baseline_average: real;
    multiplier: real;
}

func calculate_multiplier(stats) {
    let loc := stats;
    if (loc.baseline_average > 0) {
        return loc.case_count / loc.baseline_average;
    } else {
        return 0.0;
    }
}

