    let current := raw_stats[i];
    let mult := calculate_multiplier(current);
    if (mult > 3.0) {
        let new_entry := new LocationStats {
            location_name := current.location_name,
            case_count     := current.case_count,
            baseline_average := current.baseline_average,
            multiplier := mult,
        };
        filtered_locations := filtered_locations + [new_entry];
    }
}

