func compute_mean(values) {
    let sum := 0;
    for (let i := 0; i < values.length; i := i + 1) {
        sum := sum + values[i];
    }
    return sum / values.length;
}

func compute_std_dev(values, mean) {
    let sum_sq_diff := 0;
    for (let i := 0; i < values.length; i := i + 1) {
        let diff := values[i] - mean;
        sum_sq_diff := sum_sq_diff + (diff * diff);
    }
    return math.sqrt(sum_sq_diff / values.length);
}

