class DailyCounts {
    date: string;
    new_cases: int;
}

class OutbreakReport {
    outbreak_detected: bool;
    outlier_dates: array<DailyCounts>;
    iqr_value: real;
}

func detect_outbreak_and_find_outliers(daily_counts_data) {
    let counts := new Data { name := daily_counts_data };

    // Step 1: Sort data by date to ensure correct order for IQR calculation
    let sorted_counts := sort_by_date(counts);

    // Step 2: Extract new case counts into an array for statistical analysis
    let case_values := [for (let i := 0; i < sorted_counts.size; i := i + 1) {
        return sorted_counts[i].new_cases;
    }];

    // Step 3: Calculate Q1, Q3, and IQR
    let q1 := calculate_quartile(case_values, 1);
    let q3 := calculate_quartile(case_values, 3);
    let iqr := q3 - q1;

    // Step 4: Define outlier bounds
    let lower_bound := q1 - 1.5 * iqr;
    let upper_bound := q3 + 1.5 * iqr;

    // Step 5: Identify outlier days (new cases outside bounds)
    let outliers := [for (let i := 0; i < sorted_counts.size; i := i + 1) {
        let count := sorted_counts[i].new_cases;
        if (count < lower_bound || count > upper_bound) {
            return sorted_counts[i];
        }
    }];

    // Step 6: Determine if outbreak is detected (if any outliers exist)
    let outbreak_detected := (outliers.size > 0);

    // Return the report
    return new OutbreakReport {
        outbreak_detected := outbreak_detected,
        outlier_dates := outliers,
        iqr_value := iqr,
    };
}

