func calculate_z_scores(patients) {
    let bp_values := [];
    for (let i := 0; i < patients.length; i := i + 1) {
        bp_values := bp_values + [patients[i].vital_signs.blood_pressure];
    }
    let n := bp_values.length;
    let mean_bp := 0;
    for (let i := 0; i < n; i := i + 1) {
        mean_bp := mean_bp + bp_values[i];
    }
    mean_bp := mean_bp / n;

    let std_bp := 0;
    for (let i := 0; i < n; i := i + 1) {
        let diff := bp_values[i] - mean_bp;
        std_bp := std_bp + (diff * diff);
    }
    std_bp := std_bp / n;
    std_bp := std_bp.sqrt();

    let outliers := [];
    for (let i := 0; i < n; i := i + 1) {
        let diff := bp_values[i] - mean_bp;
        let z := diff / std_bp;
        let is_outlier := false;
        if (z.abs() > 2) {
            is_outlier := true;
        }
        let result := new OutlierResult {
            patient_id := patients[i].patient_id,
            is_outlier := is_outlier,
            z_score := z,
        };
        outliers := outliers + [result];
    }
    return outliers;
}

