func sort_by_cholesterol_desc(pats) {
    let sorted := pats;
    let n := length(sorted);
    for (let i := 0; i < n; i := i + 1) {
        for (let j := i + 1; j < n; j := j + 1) {
            let p1 := sorted[i];
            let p2 := sorted[j];
            let c1 := p1.lab_results.total_cholesterol;
            let c2 := p2.lab_results.total_cholesterol;
            if (c2 > c1) {
                let temp := p1;
                p1 := p2;
                p2 := temp;
                sorted[i] := p1;
                sorted[j] := p2;
            }
        }
    }
    return sorted;
}

