import statistics;

class GlucoseData {
    value: real;
}

class GlucoseDataset {
    name: string;
    data: GlucoseData[];
}

func calculate_iqr_bounds(data) {
    let sorted := data.sort_by("value");
    let n := sorted.length;
    let q1_idx := (n - 1) * 0.25;
    let q3_idx := (n - 1) * 0.75;

    let q1 := sorted[int(q1_idx)].value;
    let q3 := sorted[int(q3_idx)].value;

    let iqr := q3 - q1;

    let lower_bound := q1 - 1.5 * iqr;
    let upper_bound := q3 + 1.5 * iqr;

    return { lower_bound := lower_bound, upper_bound := upper_bound };
}

func detect_outliers(data) {
    let bounds := calculate_iqr_bounds(data);
    let outliers := [];

    for (let i := 0; i < data.length; i := i + 1) {
        let row := data[i];
        if (row.value < bounds.lower_bound || row.value > bounds.upper_bound) {
            outliers := outliers + [row];
        }
    }

    return outliers;
}

let raw_data := new GlucoseDataset { name := "glucose_measurements" };
let bounds := calculate_iqr_bounds(raw_data.data);
println("IQR Lower Bound: " + bounds.lower_bound);
println("IQR Upper Bound: " + bounds.upper_bound);

let outliers := detect_outliers(raw_data.data);
println("Number of outliers detected: " + outliers.length);

for (let i := 0; i < outliers.length; i := i + 1) {
    println("Outlier " + (i + 1) + ": " + outliers[i].value);
}

