func compute_mean_glucose_by_gender(data) {
    let grouped := new GroupedResults {
        male_mean := 0,
        female_mean := 0,
        male_count := 0,
        female_count := 0,
    };

    let raw_data := data;

    for (let i := 0; i < raw_data.size; i := i + 1) {
        let record := raw_data[i];
        let gender := record.gender;
        let glucose := record.glucose;

        if (gender == "male") {
            grouped.male_count := grouped.male_count + 1;
            grouped.male_mean := (grouped.male_mean * grouped.male_count + glucose) / (grouped.male_count + 1);
        } else if (gender == "female") {
            grouped.female_count := grouped.female_count + 1;
            grouped.female_mean := (grouped.female_mean * grouped.female_count + glucose) / (grouped.female_count + 1);
        }
    }

    return grouped;
}

