func compute_incidence_rate(data) {
    let total_cases := 0;
    let total_deaths := 0;
    let count := 0;

    for (let i := 0; i < data.length; i := i + 1) {
        let record := data[i];
        total_cases := total_cases + record.new_cases;
        total_deaths := total_deaths + record.deaths;
        count := count + 1;
    }

    let incidence_rate := (total_cases / count) * 100000;
    return incidence_rate;
}

func compute_correlation(data) {
    let n := data.length;
    let sum_x := 0;
    let sum_y := 0;
    let sum_xy := 0;
    let sum_x2 := 0;
    let sum_y2 := 0;

    for (let i := 0; i < n; i := i + 1) {
        let record := data[i];
        let x := record.new_cases;
        let y := record.deaths;

        sum_x := sum_x + x;
        sum_y := sum_y + y;
        sum_xy := sum_xy + (x * y);
        sum_x2 := sum_x2 + (x * x);
        sum_y2 := sum_y2 + (y * y);
    }

    let numerator := (n * sum_xy) - (sum_x * sum_y);
    let denominator := sqrt((n * sum_x2) - (sum_x * sum_x)) * sqrt((n * sum_y2) - (sum_y * sum_y));

    let correlation := numerator / denominator;
    return correlation;
}

