        vital_signs := new VitalSigns {
            blood_pressure := 0,
            heart_rate := 0,
        },
        lab_results := new LabResults {
            total_cholesterol := 0,
        },
    };

    for (let i := 0; i < data.patients.length; i := i + 1) {
        let current_patient := data.patients[i];
        all_patients.patients := all_patients.patients + [current_patient];
    }

    for (let i := 0; i < all_patients.patients.length; i := i + 1) {
        let p := all_patients.patients[i];
        if (p.gender == "M") {
            grouped.male_count := grouped.male_count + 1;
            grouped.male_mean := (grouped.male_mean * grouped.male_count + p.lab_results.total_cholesterol) / (grouped.male_count + 1);
        } else if (p.gender == "F") {
            grouped.female_count := grouped.female_count + 1;
            grouped.female_mean := (grouped.female_mean * grouped.female_count + p.lab_results.total_cholesterol) / (grouped.female_count + 1);
        }
    }

    return grouped;
}

