import epidemiology;

class Location {
    name: string;
}

class Epidemic {
    location: Location;
    cases: int;
    deaths: int;
}

class LocationStats {
    location_name: string;
    total_cases: int;
    total_deaths: int;
}

func aggregate_by_location(epidemics) {
    let stats_list := [];
    let seen_locations := [];

    for (let i := 0; i < epidemics.length; i := i + 1) {
        let e := epidemics[i];
        let loc := e.location;

        let found := false;
        for (let j := 0; j < seen_locations.length; j := j + 1) {
            if (seen_locations[j].name == loc.name) {
                found := true;
                seen_locations[j].total_cases := seen_locations[j].total_cases + e.cases;
                seen_locations[j].total_deaths := seen_locations[j].total_deaths + e.deaths;
                break;
            }
        }

        if (!found) {
            seen_locations := seen_locations + [new LocationStats {
                location_name := loc.name,
                total_cases := e.cases,
                total_deaths := e.deaths,
            }];
        }
    }

    return seen_locations;
}

