func aggregate_population(risk_list) {
    let total := 0;
    let high := 0;
    let medium := 0;
    let low := 0;
    let sum_score := 0.0;

    for (let i := 0; i < risk_list.length; i := i + 1) {
        let r := risk_list[i];
        total := total + 1;
        sum_score := sum_score + r.risk_score;

        if (r.risk_level == "high") {
            high := high + 1;
        } else if (r.risk_level == "medium") {
            medium := medium + 1;
        } else {
            low := low + 1;
        }
    }

    let avg := 0.0;
    if (total > 0) {
        avg := sum_score / real(total);
    }

    return new PopulationHealth {
        total_population := total,
        high_risk_count := high,
        medium_risk_count := medium,
        low_risk_count := low,
        average_risk_score := avg,
    };
}

