func normalize_glucose_column(ds) {
    let patients := healthcare.read_dataset(ds);
    let min_val := patients[0].glucose;
    let max_val := patients[0].glucose;
    for (let i := 1; i < patients.length; i := i + 1) {
        if (patients[i].glucose < min_val) {
            min_val := patients[i].glucose;
        }
        if (patients[i].glucose > max_val) {
            max_val := patients[i].glucose;
        }
    }
    let range := max_val - min_val;
    let normalized_patients := [];
    for (let i := 0; i < patients.length; i := i + 1) {
        let p := new Patient {
            patient_id := patients[i].patient_id,
            age := patients[i].age,
            gender := patients[i].gender,
            glucose := (patients[i].glucose - min_val) / range,
        };
        normalized_patients := normalized_patients + [p];
    }
    return healthcare.write_dataset(normalized_patients);
}

