let hypertension_count := 0;
let smoking_count := 0;
let total_count := 0;

for (let i := 0; i < healthcare.count(ds); i := i + 1) {
    let patient := healthcare.get_patient(ds, i);
    total_count := total_count + 1;

    let blood_pressure := patient.vital_signs.blood_pressure;
    let total_cholesterol := patient.lab_results.total_cholesterol;
    let smoking_status := patient.smoking_status;

    if (total_cholesterol >= diabetes_threshold) {
        diabetes_count := diabetes_count + 1;
    }

    if (blood_pressure >= hypertension_threshold) {
        hypertension_count := hypertension_count + 1;
    }

    if (smoking_status == "current" || smoking_status == "former") {
        smoking_count := smoking_count + 1;
    }
}

let diabetes_prevalence := (real(diabetes_count) / real(total_count)) * 100;
let hypertension_prevalence := (real(hypertension_count) / real(total_count)) * 100;
let smoking_prevalence := (real(smoking_count) / real(total_count)) * 100;

