    count: int;
}

func calculate_secondary_infections(case_data) {
    let total_cases := healthcare.get_all_cases(case_data);
    let total_secondary := 0;
    let total_cases_count := 0;

    for (let i := 0; i < total_cases; i := i + 1) {
        let current_case := total_cases[i];
        let secondary_count := healthcare.count_secondary_infections(current_case);
        total_secondary := total_secondary + secondary_count;
        total_cases_count := total_cases_count + 1;
    }

    if (total_cases_count == 0) {
        return null;
    }

    let average := total_secondary / total_cases_count;
    return average;
}

