func compute_distribution(risk_array) {
    let low := 0;
    let medium := 0;
    let high := 0;

    for (let i := 0; i < risk_array.length; i := i + 1) {
        let risk := risk_array[i];
        if (risk == "low") {
            low := low + 1;
        } else if (risk == "medium") {
            medium := medium + 1;
        } else if (risk == "high") {
            high := high + 1;
        }
    }

    return new RiskDistribution {
        low_risk := low,
        medium_risk := medium,
        high_risk := high,
    };
}

