class Patient {
    patient_id: string;
    age: int;
    gender: string;
    weight_kg: real;
}

class NormalizedPatient {
    patient_id: string;
    age: int;
    gender: string;
    weight_kg: real;
    normalized_weight: real;
}

func normalize_weight(patient) {
    let p := patient;
    let min_weight := 40.0;
    let max_weight := 120.0;
    let range := max_weight - min_weight;
    let normalized := (p.weight_kg - min_weight) / range;
    return new NormalizedPatient {
        patient_id := p.patient_id,
        age := p.age,
        gender := p.gender,
        weight_kg := p.weight_kg,
        normalized_weight := normalized,
    };
}

func sort_by_weight_desc(patients) {
    let sorted := [];
    for (let i := 0; i < patients.length; i := i + 1) {
        sorted := sorted + [patients[i]];
    }
    // Simple bubble sort for descending weight
    for (let i := 0; i < sorted.length - 1; i := i + 1) {
        for (let j := 0; j < sorted.length - i - 1; j := j + 1) {
            if (sorted[j].weight_kg < sorted[j + 1].weight_kg) {
                let temp := sorted[j];
                sorted[j] := sorted[j + 1];
                sorted[j + 1] := temp;
            }
        }
    }
    return sorted;
}

let ds := new Data { name := "patients" };
let patients := healthcare.load_dataset(ds);

let normalized_list := [];
for (let i := 0; i < patients.length; i := i + 1) {
    let n := normalize_weight(patients[i]);
    normalized_list := normalized_list + [n];
}

let sorted_patients := sort_by_weight_desc(normalized_list);

println(sorted_patients);

