import healthcare;

class VitalSigns {
    blood_pressure: int;
    heart_rate: int;
}

class LabResults {
    total_cholesterol: int;
}

class Patient {
    patient_id: string;
    age: int;
    gender: string;
    vital_signs: VitalSigns;
    lab_results: LabResults;
}

let vitals := new VitalSigns {
    blood_pressure := 128,
    heart_rate     := 0,
};

let labs := new LabResults {
    total_cholesterol := 195,
};

let patient := new Patient {
    patient_id  := "PAT008",
    age         := 48,
    gender      := "F",
    vital_signs := vitals,
    lab_results := labs,
};

let risk := healthcare.analyze_heart_disease(patient);
println(risk);
